const PR11=[{label:"Ví dụ: Cặp có tổng bằng x",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1, 3, 4, 6, 8, 11, 13};\n    int x = 15;\n    int l = 0, r = a.size() - 1;\n    while (l < r) {\n        int s = a[l] + a[r];\n        if (s == x) break;\n        if (s < x) l++;\n        else r--;\n    }\n    if (l < r) cout << a[l] << \" + \" << a[r] << \" = \" << x << \"\\n\";\n    else cout << \"Khong co\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["l","r"],range:["l","r"]},{type:"vars",names:["s","x"]}],predict:[{line:12,v:"l",q:"Sau dòng này và dòng tiếp theo, một trong hai con trỏ sẽ dịch. Con trỏ l sẽ ở ô nào? (bấm một ô)"}],py:{code:"a = [1, 3, 4, 6, 8, 11, 13]\nx = 15\nl, r = 0, len(a) - 1\nwhile l < r:\n    s = a[l] + a[r]\n    if s == x:\n        break\n    if s < x:\n        l += 1\n    else:\n        r -= 1\nif l < r:\n    print(a[l], \"+\", a[r], \"=\", x)\nelse:\n    print(\"Khong co\")",predict:[{line:8,v:"l",q:"Sau dòng này và dòng tiếp theo, một trong hai con trỏ sẽ dịch. Con trỏ l sẽ ở ô nào? (bấm một ô)"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 3, 4, 6, 8, 11, 13 };\n        int x = 15;\n        int l = 0, r = a.Length - 1;\n        while (l < r)\n        {\n            int s = a[l] + a[r];\n            if (s == x) break;\n            if (s < x) l++;\n            else r--;\n        }\n        if (l < r) Console.WriteLine(a[l] + \" + \" + a[r] + \" = \" + x);\n        else Console.WriteLine(\"Khong co\");\n    }\n}",predict:[{line:13,v:"l",q:"Sau dòng này và dòng tiếp theo, một trong hai con trỏ sẽ dịch. Con trỏ l sẽ ở ô nào? (bấm một ô)"}]}},{label:"Ví dụ: Trộn hai dãy tăng",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1, 4, 7, 9};\n    vector<int> b = {2, 3, 8, 10, 12};\n    vector<int> c;\n    int i = 0, j = 0;\n    while (i < (int)a.size() && j < (int)b.size()) {\n        if (a[i] <= b[j]) c.push_back(a[i++]);\n        else c.push_back(b[j++]);\n    }\n    while (i < (int)a.size()) c.push_back(a[i++]);\n    while (j < (int)b.size()) c.push_back(b[j++]);\n    for (int x : c) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cells",of:"b",ptr:["j"]},{type:"cells",of:"c",label:"c (kết quả)"}],py:{code:"a = [1, 4, 7, 9]\nb = [2, 3, 8, 10, 12]\nc = []\ni = j = 0\nwhile i < len(a) and j < len(b):\n    if a[i] <= b[j]:\n        c.append(a[i])\n        i += 1\n    else:\n        c.append(b[j])\n        j += 1\nwhile i < len(a):\n    c.append(a[i])\n    i += 1\nwhile j < len(b):\n    c.append(b[j])\n    j += 1\nprint(*c)"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 4, 7, 9 };\n        int[] b = { 2, 3, 8, 10, 12 };\n        List<int> c = new List<int>();\n        int i = 0, j = 0;\n        while (i < a.Length && j < b.Length)\n        {\n            if (a[i] <= b[j]) c.Add(a[i++]);\n            else c.Add(b[j++]);\n        }\n        while (i < a.Length) c.Add(a[i++]);\n        while (j < b.Length) c.Add(b[j++]);\n        Console.WriteLine(string.Join(\" \", c));\n    }\n}"}},{label:"Ví dụ: Lọc trùng tại chỗ",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {2, 2, 3, 5, 5, 5, 8, 9, 9};\n    int ghi = 1;\n    for (int doc = 1; doc < (int)a.size(); doc++) {\n        if (a[doc] != a[ghi - 1]) {\n            a[ghi] = a[doc];\n            ghi++;\n        }\n    }\n    for (int i = 0; i < ghi; i++) cout << a[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["doc","ghi"],range:["0","ghi-1"]}],py:{code:"a = [2, 2, 3, 5, 5, 5, 8, 9, 9]\nghi = 1\nfor doc in range(1, len(a)):\n    if a[doc] != a[ghi - 1]:\n        a[ghi] = a[doc]\n        ghi += 1\nprint(*a[:ghi])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 2, 2, 3, 5, 5, 5, 8, 9, 9 };\n        int ghi = 1;\n        for (int doc = 1; doc < a.Length; doc++)\n        {\n            if (a[doc] != a[ghi - 1])\n            {\n                a[ghi] = a[doc];\n                ghi++;\n            }\n        }\n        for (int i = 0; i < ghi; i++) Console.Write(a[i] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Đếm cặp có tổng không vượt x",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> a = {7, 2, 9, 4, 1, 5};\n    int x = 9;\n    sort(a.begin(), a.end());\n    int l = 0, r = a.size() - 1;\n    long long dem = 0;\n    while (l < r) {\n        if (a[l] + a[r] <= x) {\n            dem += r - l;\n            l++;\n        } else {\n            r--;\n        }\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["l","r"],range:["l","r"]},{type:"vars",names:["dem"]}],py:{code:"a = [7, 2, 9, 4, 1, 5]\nx = 9\na.sort()\nl, r = 0, len(a) - 1\ndem = 0\nwhile l < r:\n    if a[l] + a[r] <= x:\n        dem += r - l\n        l += 1\n    else:\n        r -= 1\nprint(dem)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 7, 2, 9, 4, 1, 5 };\n        int x = 9;\n        Array.Sort(a);\n        int l = 0, r = a.Length - 1;\n        long dem = 0;\n        while (l < r)\n        {\n            if (a[l] + a[r] <= x)\n            {\n                dem += r - l;\n                l++;\n            }\n            else\n            {\n                r--;\n            }\n        }\n        Console.WriteLine(dem);\n    }\n}"}}];
